\set ON_ERROR_STOP on
begin;
insert into auth.users(id) values('00000000-0000-4000-8000-000000000001');
insert into private.app_owner(owner_id) values('00000000-0000-4000-8000-000000000001');
insert into private.customers values('00000000-0000-4000-8000-000000000001','cus_synthetic',false);
select public.backend_state('session_put','{"id":"fcs_synthetic","owner_id":"00000000-0000-4000-8000-000000000001","customer_id":"cus_synthetic"}');
create function pg_temp.assert(ok boolean,message text) returns void language plpgsql as $$ begin if not coalesce(ok,false) then raise exception 'assertion: %',message; end if; end $$;
create function pg_temp.expect_error(op text,payload jsonb,code text) returns void language plpgsql as $$
begin
 begin perform public.backend_state(op,payload); exception when raise_exception then if sqlerrm=code then return; end if; raise; end;
 raise exception 'expected error % for %',code,op;
end $$;
select pg_temp.assert(not has_function_privilege('authenticated','public.backend_state(text,jsonb)','execute'),'browser cannot complete sessions directly');
select pg_temp.assert(not has_function_privilege('service_role','private.backend_state_before_linking(text,jsonb)','execute'),'previous gateway is private');
select pg_temp.expect_error('session_claim','{"id":"fcs_synthetic","owner_id":"00000000-0000-4000-8000-000000000002"}','session_not_found');
create temporary table linking_claim as select public.backend_state('session_claim','{"id":"fcs_synthetic","owner_id":"00000000-0000-4000-8000-000000000001"}') data;
select pg_temp.assert((select data->>'claim_token' is not null from linking_claim),'claim issued');
select public.backend_state('session_renew',(select data from linking_claim));
select pg_temp.expect_error('session_release',(select data||jsonb_build_object('claim_token',gen_random_uuid()) from linking_claim),'lease_lost');
select public.backend_state('session_release',(select data from linking_claim));
select pg_temp.assert(public.backend_state('session_pending','{"owner_id":"00000000-0000-4000-8000-000000000001"}')->'sessions'->0->>'status'='pending','released completion is resumable');
select pg_temp.expect_error('session_renew',(select data from linking_claim),'lease_lost');
update linking_claim set data=public.backend_state('session_claim','{"id":"fcs_synthetic","owner_id":"00000000-0000-4000-8000-000000000001"}');
select pg_temp.expect_error('session_claim','{"id":"fcs_synthetic","owner_id":"00000000-0000-4000-8000-000000000001"}','session_busy');
select pg_temp.assert(public.backend_state('session_pending','{"owner_id":"00000000-0000-4000-8000-000000000001"}')->'sessions'->0->>'status'='processing','pending summary exposes processing only');
select pg_temp.expect_error('session_accept',(select data||'{"accounts":[]}'::jsonb from linking_claim),'no_selected_accounts');
select pg_temp.assert((select count(*)=0 from public.accounts),'empty selection maps nothing');
select pg_temp.expect_error('session_accept',(select data||'{"accounts":[{"provider_id":"fca_atomicA","name":"Synthetic valid","institution":"Synthetic","kind":"cash","livemode":false},{"provider_id":"fca_atomicB","name":"Synthetic invalid","institution":"Synthetic","kind":"unsupported","livemode":true}]}'::jsonb from linking_claim),'account_mismatch');
select pg_temp.assert((select count(*)=0 from public.accounts),'invalid second account rolls back first mapping and job');
select pg_temp.expect_error('session_accept',(select data||jsonb_build_object('claim_token',gen_random_uuid(),'accounts','[{"provider_id":"fca_synthetic","livemode":false}]'::jsonb) from linking_claim),'lease_lost');
create temporary table linking_result as select public.backend_state('session_accept',(select data||'{"accounts":[{"provider_id":"fca_synthetic","name":"Synthetic cash","institution":"Synthetic bank","last_four":"1234","kind":"cash","livemode":false},{"provider_id":"fca_other","name":"Synthetic credit","institution":"Synthetic bank","last_four":"5678","kind":"credit","livemode":false}]}'::jsonb from linking_claim)) data;
select pg_temp.assert((select jsonb_array_length(data->'accountIds')=2 and data->>'status'='queued' from linking_result),'all selections accepted atomically');
select pg_temp.assert((select count(*)=2 from private.jobs where kind='subscribe' and status='queued'),'durable subscriptions before provider calls');
select pg_temp.assert((select count(*)=2 from public.accounts where sync_error='subscription_pending'),'subscription pending visible');
select pg_temp.assert((select count(*)=0 from private.refresh_usage),'completion does not reserve paid balances');
select pg_temp.assert(public.backend_state('session_pending','{"owner_id":"00000000-0000-4000-8000-000000000001"}')='{"sessions":[]}'::jsonb,'accepted session no longer pending');
select pg_temp.assert(public.backend_state('session_accept','{"id":"fcs_synthetic","owner_id":"00000000-0000-4000-8000-000000000001"}')=(select data from linking_result),'replay returns result before validating lease or selections');
select pg_temp.assert(public.backend_state('session_claim','{"id":"fcs_synthetic","owner_id":"00000000-0000-4000-8000-000000000001"}')->'completion_result'=(select data from linking_result),'completed claim returns recorded result');
select pg_temp.assert(public.backend_state('mapping','{"provider_id":"fca_synthetic"}')->>'customer_id'='cus_synthetic','mapping includes authoritative account holder customer');
update private.jobs set status='failed',attempts=8,error='provider_timeout' where kind='subscribe';
create temporary table subscription_ids as select id from private.jobs where kind='subscribe';
select public.backend_state('subscription_retry',jsonb_build_object('account_id',account_id)) from private.provider_accounts;
select pg_temp.assert((select count(*)=2 from private.jobs where kind='subscribe' and status='queued' and attempts=0 and id in (select id from subscription_ids)),'explicit owner retry keeps same durable subscription identity');
insert into private.jobs(account_id,kind,dedupe_key) select account_id,'lifecycle','event:active-before-subscribe' from private.provider_accounts where provider_id='fca_other';
update private.jobs set available_at=clock_timestamp()+interval '1 day' where kind='subscribe';
create temporary table lifecycle_job as select public.backend_state('claim') data;
select public.backend_state('lifecycle',(select data||'{"provider_status":"active"}'::jsonb from lifecycle_job));
select pg_temp.assert((select count(*)=2 from public.accounts where sync_error='subscription_pending'),'authoritative active lifecycle preserves independent pending subscription');
insert into private.jobs(account_id,kind,dedupe_key) select account_id,'lifecycle','event:inactive-before-subscribe' from private.provider_accounts where provider_id='fca_other';
truncate lifecycle_job;
insert into lifecycle_job select public.backend_state('claim');
select public.backend_state('lifecycle',(select data||'{"provider_status":"inactive"}'::jsonb from lifecycle_job));
select pg_temp.assert((select connection_state='error' and sync_error='connection_inactive' from public.accounts where id=(select (data->>'account_id')::uuid from lifecycle_job)),'authoritative inactive state visible');
insert into private.jobs(account_id,kind,dedupe_key) select (data->>'account_id')::uuid,'lifecycle','event:reactive-before-subscribe' from lifecycle_job;
truncate lifecycle_job;
insert into lifecycle_job select public.backend_state('claim');
select public.backend_state('lifecycle',(select data||'{"provider_status":"active"}'::jsonb from lifecycle_job));
select pg_temp.assert((select count(*)=2 from public.accounts where connection_state='active' and sync_error='subscription_pending'),'reactivation restores pending subscription, not false success');
update private.jobs set available_at=clock_timestamp() where kind='subscribe';
create temporary table active_job as select public.backend_state('claim') data;
select pg_temp.expect_error('subscribe_finish',(select data||jsonb_build_object('lease_token',gen_random_uuid()) from active_job),'lease_lost');
select public.backend_state('subscribe_started',(select data from active_job));
select public.backend_state('job_renew',(select data from active_job));
select pg_temp.assert((select lease_until>clock_timestamp()+interval '85 seconds' from private.jobs where id=(select (data->>'id')::uuid from active_job)),'subscribe start renews lease');
select public.backend_state('subscribe_finish',(select data from active_job));
select pg_temp.assert((select count(*)=1 from private.provider_accounts where subscribed),'leased subscription published');
select pg_temp.assert((select count(*)=1 from private.jobs where kind='sync' and dedupe_key like 'initial:%'),'initial sync durably enqueued');
select pg_temp.assert((select count(*)=1 from public.accounts where sync_error='transactions_not_ready'),'initial asynchronous sync visible');
-- Successful work must not erase independent balance/subscription outcomes.
update private.jobs set available_at=clock_timestamp()+interval '1 day' where kind='subscribe' and status='queued';
truncate active_job;
insert into active_job select public.backend_state('claim');
update public.accounts set sync_error='balance_unavailable' where id=(select (data->>'account_id')::uuid from active_job);
select public.backend_state('finish',(select data from active_job));
select pg_temp.assert((select sync_error='balance_unavailable' from public.accounts where id=(select (data->>'account_id')::uuid from active_job)),'transaction success preserves unavailable balance');
insert into private.jobs(account_id,kind,dedupe_key) select (data->>'account_id')::uuid,'lifecycle','event:active-after-balance' from active_job;
truncate active_job;
insert into active_job select public.backend_state('claim');
select public.backend_state('lifecycle',(select data||'{"provider_status":"active"}'::jsonb from active_job));
select pg_temp.assert((select sync_error='balance_unavailable' from public.accounts where id=(select (data->>'account_id')::uuid from active_job)),'active lifecycle preserves unavailable balance');
insert into private.jobs(account_id,kind,dedupe_key) select (data->>'account_id')::uuid,'balance','event:balance-success' from active_job;
truncate active_job;
insert into active_job select public.backend_state('claim');
update public.accounts set sync_error='transactions_not_ready' where id=(select (data->>'account_id')::uuid from active_job);
select public.backend_state('finish',(select data from active_job));
select pg_temp.assert((select sync_error='transactions_not_ready' from public.accounts where id=(select (data->>'account_id')::uuid from active_job)),'balance success preserves pending transactions');
insert into private.jobs(account_id,kind,dedupe_key) select (data->>'account_id')::uuid,'sync','event:next-sync' from active_job;
-- Keep the other account out of this sequence so every claim below targets the subscribed account.
update private.jobs set available_at=clock_timestamp()+interval '1 day' where kind='subscribe' and status='queued';
truncate active_job;
insert into active_job select public.backend_state('claim');
select public.backend_state('disconnect_request',jsonb_build_object('account_id',(select data->>'account_id' from active_job),'kind','disconnect','dedupe_key','disconnect:synthetic'));
select pg_temp.assert(public.backend_state('claim')='{}'::jsonb,'disconnect waits for prior in-flight account lease');
select pg_temp.expect_error('page',(select data||'{"rows":[]}'::jsonb from active_job),'disconnecting');
select pg_temp.expect_error('balance_started',(select data from active_job),'disconnecting');
select pg_temp.expect_error('job_renew',(select data from active_job),'disconnecting');
select pg_temp.expect_error('subscription_retry',jsonb_build_object('account_id',(select data->>'account_id' from active_job)),'disconnecting');
select pg_temp.expect_error('map_account',public.backend_state('mapping',jsonb_build_object('account_id',(select data->>'account_id' from active_job)))||'{"name":"Do not revive","kind":"cash","institution":"Synthetic"}'::jsonb,'disconnecting');
select public.backend_state('retry',(select data||'{"error":"provider_timeout"}'::jsonb from active_job));
select pg_temp.assert((select status='done' and error='disconnecting' from private.jobs where id=(select (data->>'id')::uuid from active_job)),'disconnect cancels interrupted sync without retry');
truncate active_job;
insert into active_job select public.backend_state('claim');
select pg_temp.assert((select data->>'kind'='disconnect' from active_job),'disconnect claims after prior lease');
select public.backend_state('disconnected',(select data from active_job));
select public.backend_state('finish',(select data from active_job));
select pg_temp.assert((select count(*)=1 from public.accounts where connection_state='disconnected'),'history retained on disconnect');
select pg_temp.assert(public.backend_state('session_accept','{"id":"fcs_synthetic","owner_id":"00000000-0000-4000-8000-000000000001"}')=(select data from linking_result),'completion replay after disconnect is inert');
select pg_temp.assert((select count(*)=1 from public.accounts where connection_state='disconnected'),'replay cannot reactivate account');
-- Lifecycle jobs retrieve authoritative state, but cannot undo local intent.
insert into private.jobs(account_id,kind,dedupe_key) select (data->>'account_id')::uuid,'lifecycle','event:late-active' from active_job;
truncate active_job;
insert into active_job select public.backend_state('claim');
select public.backend_state('lifecycle',(select data||'{"provider_status":"active"}'::jsonb from active_job));
select pg_temp.assert((select count(*)=1 from public.accounts where connection_state='disconnected'),'late active event respects local intent');
-- A subscription in flight must reconcile through disconnect, never publish success.
update private.jobs set available_at=clock_timestamp() where kind='subscribe' and status='queued';
truncate active_job;
insert into active_job select public.backend_state('claim');
select public.backend_state('subscribe_started',(select data from active_job));
select public.backend_state('disconnect_request',jsonb_build_object('account_id',(select data->>'account_id' from active_job),'kind','disconnect','dedupe_key','disconnect:other'));
select pg_temp.expect_error('subscribe_started',(select data from active_job),'disconnecting');
select pg_temp.expect_error('subscribe_finish',(select data from active_job),'disconnecting');
select pg_temp.assert(public.backend_state('claim')='{}'::jsonb,'in-flight subscription blocks disconnect lease');
update private.jobs set lease_until=clock_timestamp()-interval '1 second' where id=(select (data->>'id')::uuid from active_job);
truncate active_job;
insert into active_job select public.backend_state('claim');
select pg_temp.assert((select data->>'kind'='disconnect' from active_job),'expired subscription lease yields to disconnect reconciliation');
select public.backend_state('retry',(select data||'{"error":"private bank error secret 1234"}'::jsonb from active_job));
select pg_temp.assert((select error='provider_unavailable' from private.jobs where id=(select (data->>'id')::uuid from active_job)),'untrusted errors sanitized');
select pg_temp.assert((select count(*)=0 from private.jobs where kind='subscribe' and status='queued'),'expired subscription cannot restart after disconnect intent');
update private.jobs set status='processing',attempts=8,lease_token=gen_random_uuid(),lease_until=clock_timestamp()+interval '90 seconds' where id=(select (data->>'id')::uuid from active_job);
update active_job set data=(select to_jsonb(j) from private.jobs j where j.id=(data->>'id')::uuid);
select public.backend_state('retry',(select data||'{"error":"provider_timeout"}'::jsonb from active_job));
select pg_temp.assert((select status='failed' and error='provider_timeout' from private.jobs where id=(select (data->>'id')::uuid from active_job)),'exhaustion preserves sanitized root failure on job');
select pg_temp.assert((select sync_error='retry_exhausted' from public.accounts where id=(select (data->>'account_id')::uuid from active_job)),'exhaustion remains visible to owner');
-- Permanent local deletion cannot erase the provider-ID fence against stale completion.
update private.jobs set status='queued',attempts=0,available_at=clock_timestamp(),delete_local=true where id=(select (data->>'id')::uuid from active_job);
create temporary table deleted_mapping as select public.backend_state('mapping',jsonb_build_object('account_id',(select data->>'account_id' from active_job))) data;
truncate active_job;
insert into active_job select public.backend_state('claim');
select public.backend_state('disconnected',(select data from active_job));
select public.backend_state('finish',(select data from active_job));
select pg_temp.assert((select count(*)=0 from private.provider_accounts where provider_id=(select data->>'provider_id' from deleted_mapping)),'local deletion removes account mapping');
select pg_temp.expect_error('map_account',(select data||'{"name":"Stale completion","institution":"Synthetic","kind":"cash"}'::jsonb from deleted_mapping),'disconnecting');
select pg_temp.assert((select count(*)=1 from public.accounts),'stale map cannot recreate deleted account');
-- Paid uncertainty correlation is captured once, not moved forward by retries.
insert into public.accounts(id,owner_id,source,name,kind,connection_state) values('10000000-0000-4000-8000-000000000099','00000000-0000-4000-8000-000000000001','stripe','Synthetic balance','cash','active');
insert into private.jobs(account_id,kind,dedupe_key) values('10000000-0000-4000-8000-000000000099','balance','refresh:synthetic-baseline');
truncate active_job;
insert into active_job select public.backend_state('claim');
select public.backend_state('balance_started',(select data||'{"baseline_as_of":1794330000}'::jsonb from active_job));
create temporary table balance_dispatch as select balance_dispatch_at from private.jobs where id=(select (data->>'id')::uuid from active_job);
select public.backend_state('balance_started',(select data||'{"baseline_as_of":1794339999}'::jsonb from active_job));
select pg_temp.assert((select paid_started and balance_baseline=1794330000 and balance_dispatch_at=(select balance_dispatch_at from balance_dispatch) from private.jobs where id=(select (data->>'id')::uuid from active_job)),'balance retry cannot overwrite original correlation baseline');
select public.backend_state('retry',(select data||'{"error":"connection_inactive"}'::jsonb from active_job));
select pg_temp.assert((select connection_state='error' and sync_error='connection_inactive' from public.accounts where id=(select (data->>'account_id')::uuid from active_job)),'provider inactive failure cannot appear publicly healthy');
update private.jobs set available_at=clock_timestamp() where id=(select (data->>'id')::uuid from active_job);
truncate active_job;
insert into active_job select public.backend_state('claim');
update public.accounts set sync_error='balance_not_ready' where id=(select (data->>'account_id')::uuid from active_job);
select public.backend_state('balance_snapshot',(select data||jsonb_build_object('current_minor',123,'observed_at',clock_timestamp()) from active_job));
select pg_temp.assert((select count(*)=1 from public.balance_snapshots where account_id=(select (data->>'account_id')::uuid from active_job)),'authoritatively reactivated balance is not silently dropped');
select pg_temp.assert((select connection_state='active' from public.accounts where id=(select (data->>'account_id')::uuid from active_job)),'validated balance restores inactive connection');
select public.backend_state('finish',(select data from active_job));
select public.backend_state('reserve',jsonb_build_object('account_id',(select data->>'account_id' from active_job)));
select pg_temp.assert((select sync_error='balance_not_ready' from public.accounts where id=(select (data->>'account_id')::uuid from active_job)),'reservation immediately exposes pending balance');
truncate active_job;
insert into active_job select public.backend_state('claim');
update private.jobs set attempts=8 where id=(select (data->>'id')::uuid from active_job);
select public.backend_state('retry',(select data||'{"error":"balance_not_ready"}'::jsonb from active_job));
select pg_temp.assert((select sync_error='balance_not_ready' from public.accounts where id=(select (data->>'account_id')::uuid from active_job)),'async pending is not misreported as terminal provider failure');
select pg_temp.assert((select status='failed' and error='balance_not_ready' from private.jobs where id=(select (data->>'id')::uuid from active_job)),'pending job still respects retry budget');
rollback;
